'use strict';
(function(root,factory){const api=factory();if(typeof module==='object'&&module.exports)module.exports=api;if(root)root.MIRWorkshopQueue=api})(typeof window==='object'?window:null,function(){
const clone=v=>JSON.parse(JSON.stringify(v));const text=v=>String(v??'').trim();const now=v=>v?new Date(v).toISOString():new Date().toISOString();const makeId=p=>`${p}-${Date.now()}-${Math.random().toString(36).slice(2,8)}`;const assert=(c,m)=>{if(!c)throw new Error(m)};
function conflict(e,a){const x=new Error(`Conflit de révision : attendu ${e}, actuel ${a}`);x.code='REVISION_CONFLICT';return x}
function createWorkshopQueue({organizationId='MIR',now:at}={}){return{schemaVersion:1,organizationId:text(organizationId)||'MIR',revision:1,jobs:[],events:[],idempotencyKeys:[],createdAt:now(at),updatedAt:now(at)}}
function ensure(s,r){if(!Number.isInteger(r))throw new Error('expectedRevision requis');if(r!==s.revision)throw conflict(r,s.revision)}
function mutate(s,r,kind,at){ensure(s,r);const n=clone(s);n.revision+=1;n.updatedAt=now(at);n.events.push({kind,at:n.updatedAt,revision:n.revision});return n}
function enqueueRelease(state,release,{expectedRevision,actorRole='admin',now:at}={}){assert(actorRole==='admin','Admin requis pour libérer vers atelier');assert(release?.immutable===true&&release?.snapshot,'Libération production immuable requise');const key=`release:${release.id}:${release.contentFingerprint}`;if(state.idempotencyKeys.includes(key))return clone(state);let n=mutate(state,expectedRevision,'release-enqueued',at);for(const item of release.snapshot.items||[]){n.jobs.push({id:makeId('job'),organizationId:n.organizationId,releaseId:release.id,releaseNumber:release.releaseNumber,contentFingerprint:release.contentFingerprint,batchId:release.batchId,chantierId:release.snapshot.chantierId||'',chantierName:release.snapshot.chantierName||'',sourceItemId:item.sourceItemId||item.id,itemId:item.id,description:item.description||item.id,material:item.material||'',gauge:item.gauge||'',color:item.color||'',quantityRequested:Number(item.quantity||0),quantityCompleted:0,status:'queued',assignedTo:null,startedAt:null,completedAt:null,history:[{kind:'queued',at:n.updatedAt}],sourceSnapshot:clone(item)});}n.idempotencyKeys.push(key);return n}
function findJob(s,id){const i=s.jobs.findIndex(j=>j.id===id);if(i<0)throw new Error('Tâche atelier inconnue');return i}
function assignJob(state,{jobId,userId,actorRole='admin'},{expectedRevision,now:at}={}){assert(actorRole==='admin','Admin requis pour assigner');assert(text(userId),'Employé requis');const i=findJob(state,jobId);assert(!['completed','cancelled'].includes(state.jobs[i].status),'Tâche fermée');const n=mutate(state,expectedRevision,'job-assigned',at);n.jobs[i].assignedTo=text(userId);n.jobs[i].history.push({kind:'assigned',userId:text(userId),at:n.updatedAt});return n}
function startJob(state,{jobId,userId},{expectedRevision,now:at}={}){const i=findJob(state,jobId);const j=state.jobs[i];assert(j.status!=='completed'&&j.status!=='cancelled','Tâche fermée');assert(!j.assignedTo||j.assignedTo===text(userId),'Tâche assignée à un autre employé');const n=mutate(state,expectedRevision,'job-started',at);const x=n.jobs[i];x.assignedTo=x.assignedTo||text(userId);x.status=x.quantityCompleted>0?'partial':'in_progress';x.startedAt=x.startedAt||n.updatedAt;x.history.push({kind:'started',userId:text(userId),at:n.updatedAt});return n}
function recordProduction(state,{jobId,quantity,idempotencyKey,userId,note=''},{expectedRevision,now:at}={}){const key=text(idempotencyKey);assert(key,'Clé idempotence requise');if(state.idempotencyKeys.includes(key))return clone(state);const i=findJob(state,jobId);const j=state.jobs[i];assert(!['completed','cancelled'].includes(j.status),'Tâche fermée');assert(!j.assignedTo||j.assignedTo===text(userId),'Tâche assignée à un autre employé');const q=Number(quantity);assert(Number.isFinite(q)&&q>0,'Quantité produite invalide');assert(j.quantityCompleted+q<=j.quantityRequested+1e-9,'Quantité produite supérieure au requis');const n=mutate(state,expectedRevision,'production-recorded',at);const x=n.jobs[i];x.assignedTo=x.assignedTo||text(userId);x.startedAt=x.startedAt||n.updatedAt;x.quantityCompleted+=q;x.status=x.quantityCompleted>=x.quantityRequested?'completed':'partial';if(x.status==='completed')x.completedAt=n.updatedAt;x.history.push({kind:'produced',quantity:q,userId:text(userId),note:text(note),at:n.updatedAt,idempotencyKey:key});n.idempotencyKeys.push(key);return n}
function cancelJob(state,{jobId,reason='',actorRole='admin'},{expectedRevision,now:at}={}){assert(actorRole==='admin','Admin requis pour annuler');const i=findJob(state,jobId);const j=state.jobs[i];assert(j.quantityCompleted===0,'Une tâche déjà produite ne peut pas être annulée');assert(j.status!=='completed','Tâche déjà terminée');if(j.status==='cancelled')return clone(state);const n=mutate(state,expectedRevision,'job-cancelled',at);n.jobs[i].status='cancelled';n.jobs[i].history.push({kind:'cancelled',reason:text(reason),at:n.updatedAt});return n}
function releaseSummary(state,releaseId){const jobs=state.jobs.filter(j=>j.releaseId===releaseId);const active=jobs.filter(j=>j.status!=='cancelled');const requested=active.reduce((s,j)=>s+j.quantityRequested,0);const completed=active.reduce((s,j)=>s+j.quantityCompleted,0);return{jobs:jobs.length,activeJobs:active.length,requested,completed,remaining:Math.max(0,requested-completed),complete:active.length>0&&active.every(j=>j.status==='completed'),statuses:Object.fromEntries(['queued','in_progress','partial','completed','cancelled'].map(k=>[k,jobs.filter(j=>j.status===k).length]))}}
function listJobs(state,{status='',assignedTo='',chantierId='',query=''}={}){const q=text(query).toLowerCase();return state.jobs.filter(j=>(!status||j.status===status)&&(!assignedTo||j.assignedTo===assignedTo)&&(!chantierId||j.chantierId===chantierId)&&(!q||`${j.description} ${j.material} ${j.color} ${j.chantierName} ${j.sourceItemId}`.toLowerCase().includes(q))).map(clone)}
function serialize(s){return JSON.stringify(s,null,2)}function restore(raw){const s=typeof raw==='string'?JSON.parse(raw):clone(raw);assert(s?.schemaVersion===1&&Number.isInteger(s.revision),'File atelier invalide');s.jobs=Array.isArray(s.jobs)?s.jobs:[];s.events=Array.isArray(s.events)?s.events:[];s.idempotencyKeys=Array.isArray(s.idempotencyKeys)?s.idempotencyKeys:[];return s}
return{createWorkshopQueue,enqueueRelease,assignJob,startJob,recordProduction,cancelJob,releaseSummary,listJobs,serialize,restore};
});
